using System.ComponentModel;
using System.Text.Json;
using System.Text.RegularExpressions;
using Microsoft.Extensions.AI;
using OpenAI;

// ---------------------------------------------------------------------------
// Configuration
// ---------------------------------------------------------------------------
var modelName = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini";
var apiKey    = Environment.GetEnvironmentVariable("OPENAI_API_KEY");
var endpoint  = Environment.GetEnvironmentVariable("OPENAI_BASE_URL");

if (string.IsNullOrWhiteSpace(apiKey))
{
    Console.Error.WriteLine("Set the OPENAI_API_KEY environment variable.");
    return 1;
}

IChatClient chatClient;
if (!string.IsNullOrWhiteSpace(endpoint))
{
    var clientOptions = new OpenAIClientOptions { Endpoint = new Uri(endpoint) };
    chatClient = new OpenAIClient(apiKey, clientOptions)
        .GetChatClient(modelName)
        .AsIChatClient();
}
else
{
    chatClient = new OpenAIClient(apiKey)
        .GetChatClient(modelName)
        .AsIChatClient();
}

// ---------------------------------------------------------------------------
// Tools
// ---------------------------------------------------------------------------
var notebook = new Notebook();
var webSearch = new WebSearchTool();

var tools = new[]
{
    AIFunctionFactory.Create(webSearch.SearchWeb),
    AIFunctionFactory.Create(notebook.AddNote),
    AIFunctionFactory.Create(notebook.GetNotes),
};

var chatOptions = new ChatOptions { Tools = [.. tools] };

// ---------------------------------------------------------------------------
// Prompt the user for a research topic
// ---------------------------------------------------------------------------
Console.Write("Enter a research topic: ");
var topic = Console.ReadLine()?.Trim();
if (string.IsNullOrWhiteSpace(topic))
{
    Console.Error.WriteLine("No topic provided.");
    return 1;
}

Console.WriteLine($"\nResearching: {topic}\n");

// ---------------------------------------------------------------------------
// Agent loop
// ---------------------------------------------------------------------------
List<ChatMessage> messages =
[
    new(ChatRole.System, """
        You are a research agent. Your job is to research the topic the user gives you.

        You have access to three tools:
        1. SearchWeb  – search the web for information. Use varied queries to get broad coverage.
        2. AddNote    – save an important finding so you remember it.
        3. GetNotes   – retrieve all notes you have saved so far.

        Workflow:
        - Perform 2-4 web searches with different queries to gather information.
        - After each search, save the key facts as notes using AddNote.
        - Once you have enough material, call GetNotes to review everything.
        - Finally, write a comprehensive summary for the user. Include key findings,
          important details, and cite sources where possible.
        """),
    new(ChatRole.User, $"Please research the following topic: {topic}")
];

const int maxIterations = 20;
for (int i = 0; i < maxIterations; i++)
{
    var response = await chatClient.GetResponseAsync(messages, chatOptions);

    // Merge assistant response into the conversation
    messages.AddMessages(response);

    if (response.Messages.Any(m => m.Contents.OfType<FunctionCallContent>().Any()))
    {
        // Tool calls were made – continue the loop so the model can process results
        continue;
    }

    // No tool calls – the agent is done; print its final answer
    var finalText = string.Concat(
        response.Messages
            .SelectMany(m => m.Contents)
            .OfType<TextContent>()
            .Select(t => t.Text));

    Console.WriteLine("═══════════════════════════════════════════════════");
    Console.WriteLine("  RESEARCH SUMMARY");
    Console.WriteLine("═══════════════════════════════════════════════════");
    Console.WriteLine(finalText);
    Console.WriteLine("═══════════════════════════════════════════════════");
    Console.WriteLine($"\nNotes collected: {notebook.Count}");
    break;
}

return 0;

// ═══════════════════════════════════════════════════════════════════════════
// Notebook tool – lets the agent save and retrieve research notes
// ═══════════════════════════════════════════════════════════════════════════
sealed class Notebook
{
    private readonly List<string> _notes = [];

    public int Count => _notes.Count;

    [Description("Save an important research finding as a note.")]
    public string AddNote(
        [Description("The note text to save")] string note)
    {
        _notes.Add(note);
        Console.WriteLine($"  📝 Note #{_notes.Count}: {Truncate(note, 100)}");
        return $"Note saved (total: {_notes.Count}).";
    }

    [Description("Retrieve all saved research notes.")]
    public string GetNotes()
    {
        if (_notes.Count == 0)
            return "No notes saved yet.";

        return string.Join("\n", _notes.Select((n, i) => $"[{i + 1}] {n}"));
    }

    private static string Truncate(string s, int max) =>
        s.Length <= max ? s : s[..max] + "…";
}

// ═══════════════════════════════════════════════════════════════════════════
// Web search tool – uses DuckDuckGo HTML to search without an API key
// ═══════════════════════════════════════════════════════════════════════════
sealed class WebSearchTool
{
    private static readonly HttpClient Http = new()
    {
        DefaultRequestHeaders =
        {
            { "User-Agent", "ResearchAgent/1.0" }
        },
        Timeout = TimeSpan.FromSeconds(15)
    };

    [Description("Search the web for information on a query. Returns a list of result titles, URLs, and snippets.")]
    public async Task<string> SearchWeb(
        [Description("The search query")] string query)
    {
        Console.WriteLine($"  🔍 Searching: {query}");

        try
        {
            var url = $"https://html.duckduckgo.com/html/?q={Uri.EscapeDataString(query)}";
            var html = await Http.GetStringAsync(url);

            var results = ParseResults(html);
            if (results.Count == 0)
                return "No results found.";

            return JsonSerializer.Serialize(results, new JsonSerializerOptions { WriteIndented = true });
        }
        catch (Exception ex)
        {
            return $"Search failed: {ex.Message}";
        }
    }

    private static List<SearchResult> ParseResults(string html)
    {
        var results = new List<SearchResult>();

        // Match DuckDuckGo HTML result blocks
        var snippetRegex = new Regex(
            @"<a[^>]+class=""result__a""[^>]*href=""([^""]*)""[^>]*>(.*?)</a>.*?<a[^>]+class=""result__snippet""[^>]*>(.*?)</a>",
            RegexOptions.Singleline);

        foreach (Match match in snippetRegex.Matches(html))
        {
            if (results.Count >= 6) break;

            var link = match.Groups[1].Value;
            // DuckDuckGo wraps links through a redirect; extract the real URL
            var uddgMatch = Regex.Match(link, @"uddg=([^&]+)");
            var realUrl = uddgMatch.Success
                ? Uri.UnescapeDataString(uddgMatch.Groups[1].Value)
                : link;

            results.Add(new SearchResult
            {
                Title   = StripHtml(match.Groups[2].Value),
                Url     = realUrl,
                Snippet = StripHtml(match.Groups[3].Value)
            });
        }

        return results;
    }

    private static string StripHtml(string s) =>
        Regex.Replace(s, "<.*?>", "").Trim();

    private record SearchResult
    {
        public string Title   { get; init; } = "";
        public string Url     { get; init; } = "";
        public string Snippet { get; init; } = "";
    }
}

