// ═══════════════════════════════════════════════════════════════════════════
// Web search tool – uses DuckDuckGo HTML to search without an API key
// ═══════════════════════════════════════════════════════════════════════════
sealed class WebSearchTool
{
    private static readonly HttpClient Http = new()
    {
        DefaultRequestHeaders =
        {
            { "User-Agent", "ResearchAgent/1.0" }
        },
        Timeout = TimeSpan.FromSeconds(15)
    };

    [Description("Search the web for information on a query. Returns a list of result titles, URLs, and snippets.")]
    public async Task<string> SearchWeb(
        [Description("The search query")] string query)
    {
        Console.WriteLine($"  🔍 Searching: {query}");

        try
        {
            var url = $"https://html.duckduckgo.com/html/?q={Uri.EscapeDataString(query)}";
            var html = await Http.GetStringAsync(url);

            var results = ParseResults(html);
            if (results.Count == 0)
                return "No results found.";

            return JsonSerializer.Serialize(results, new JsonSerializerOptions { WriteIndented = true });
        }
        catch (Exception ex)
        {
            return $"Search failed: {ex.Message}";
        }
    }

    private static List<SearchResult> ParseResults(string html)
    {
        var results = new List<SearchResult>();

        // Match DuckDuckGo HTML result blocks
        var snippetRegex = new Regex(
            @"<a[^>]+class=""result__a""[^>]*href=""([^""]*)""[^>]*>(.*?)</a>.*?<a[^>]+class=""result__snippet""[^>]*>(.*?)</a>",
            RegexOptions.Singleline);

        foreach (Match match in snippetRegex.Matches(html))
        {
            if (results.Count >= 6) break;

            var link = match.Groups[1].Value;
            // DuckDuckGo wraps links through a redirect; extract the real URL
            var uddgMatch = Regex.Match(link, @"uddg=([^&]+)");
            var realUrl = uddgMatch.Success
                ? Uri.UnescapeDataString(uddgMatch.Groups[1].Value)
                : link;

            results.Add(new SearchResult
            {
                Title   = StripHtml(match.Groups[2].Value),
                Url     = realUrl,
                Snippet = StripHtml(match.Groups[3].Value)
            });
        }

        return results;
    }

    private static string StripHtml(string s) =>
        Regex.Replace(s, "<.*?>", "").Trim();

    private record SearchResult
    {
        public string Title   { get; init; } = "";
        public string Url     { get; init; } = "";
        public string Snippet { get; init; } = "";
    }
}

